$items = Get-Content "TradeItems.txt" | Where-Object { $_.Trim() }; $json = Get-Content "TradeItems.json" -Raw | ConvertFrom-Json; $jsonChildren = @(); foreach ($t in $json) { if ($t.Children) { $jsonChildren += $t.Children } }; $jsonChildren = $jsonChildren | Select-Object -Unique; $missing = $items | Where-Object { $_.Trim() -notin $jsonChildren }; Write-Output "Missing: $($missing.Count)"; $missing